body=f'''<video id="roomblur" src="assets/clipes/ambiente.mp4" muted data-start="0" data-duration="{B}"></video><video id="palestra" src="assets/clipes/palestra.mp4" muted data-start="0" data-duration="{B}"></video><video id="mesa" src="assets/clipes/mesa.mp4" muted data-start="{B}" data-duration="{T-B}"></video><div id="tint"></div><div id="credit">Mohammed Qahtani<br><span>The Power of Words · Toastmasters, 2015</span></div><div id="speakerLabel">DUBLAGEM EM PORTUGUÊS</div><div id="quoteContext">DEMONSTRAÇÃO SOBRE PERSUASÃO · ARGUMENTOS FICTÍCIOS</div><div id="motion"><div id="brand">PROCESSOS & IA</div><div id="editorial">Falar com confiança.<br><span class="serif">Dizer a verdade.</span><div id="strike"></div></div><div id="bridgeNote">Uma coisa não garante a outra.</div><div id="example">EXEMPLO ILUSTRATIVO</div><div id="paperWorld"><div id="under"><span style="font-size:23px;letter-spacing:3px">O QUE FICOU FORA</span><h2>Por trás da resposta.</h2><div class="ledgerRow" id="cost"><strong>Custo</strong><span>DESATUALIZADO</span></div><div class="ledgerRow" id="freight"><strong>Frete</strong><span>NÃO INCLUÍDO</span></div><div id="profit">Margem do pedido<div id="track"><div id="profitBar"></div></div><div id="profitEnd">O lucro não veio.</div></div><div id="sale">✓ Venda aprovada</div></div><div id="receipt"><div id="paperHead"><b>Pedido</b><span>COMERCIAL</span></div><div id="ask">Posso dar desconto<br>nesse pedido?</div><div id="answer">Pode aprovar.<small>O desconto é viável para este pedido.</small></div><div id="approve">Aprovar desconto</div><div id="stamp">APROVADO</div></div><svg id="cursor" viewBox="0 0 80 110"><path d="M8 5v82l21-21 18 35 17-9-17-33h30Z" fill="white" stroke="#203d36" stroke-width="4"/></svg></div><div id="process"><h2 id="processTitle">A resposta precisa de um caminho.</h2><div id="l1" class="line"></div><div id="l2" class="line"></div><div id="beam"></div><div id="n1" class="node">{svgdoc}<div><b>Dados conferidos</b><p>Antes de entrar na conta</p></div><span class="tick">✓</span></div><div id="n2" class="node">{svgcalc}<div><b>Ferramenta de cálculo</b><p>A conta fora do palpite</p></div><span class="tick">✓</span></div><div id="n3" class="node">{svgperson}<div><b>Responsável pela decisão</b><p>Confere e aprova</p></div><span class="tick">✓</span></div></div><div id="final"><h1>Você consegue<br><em>conferir o caminho?</em></h1><div class="rule"></div><p>Vamos olhar o seu processo.</p><div id="finalcard"><small>COMENTA</small><b>DIAGNÓSTICO ↗</b></div></div><div id="source">IA e respostas incorretas: OpenAI · Why language models hallucinate</div></div><img id="logo" src="assets/marca/logo-branca.png"><div id="captions"></div><audio id="master" src="assets/audio/master.wav" data-start="0" data-duration="{T}"></audio><audio id="music" src="assets/audio/trilha.mp3" data-start="{B}" data-duration="{T-B}" data-volume="0.06" data-fade-in="1" data-fade-out="2"></audio>'''
js='''const tl=gsap.timeline({paused:true});const B=D.bridge,T=D.total,W=D.words,S=D.starts;window.__timelines={main:tl};
function cue(word,after=B){return W.find(x=>x.s>=after&&x.w.toLowerCase().replace(/[.,?!:]/g,'')===word)?.s??after;}
function enter(sel,at,from={y:70},duration=.65){tl.set(sel,{opacity:0},0);tl.fromTo(sel,{...from,opacity:0},{y:0,x:0,scale:1,rotation:0,rotationY:0,opacity:1,duration,ease:'power3.out'},at);}
function hide(sel,at){tl.set(sel,{opacity:0},at);}
tl.set('#palestra,#roomblur,#credit,#speakerLabel,#quoteContext',{opacity:0},B);tl.set('#mesa,#motion',{opacity:1},B);tl.fromTo('#mesa',{scale:1.06},{scale:1.18,duration:T-B,ease:'none'},B);
const Q=S[1],P=S[2],F=S[3];
enter('#editorial',B,{y:40});enter('#bridgeNote',cue('verdade',B),{y:20});tl.set('#strike',{scaleX:0},0);tl.to('#strike',{scaleX:1,duration:.35,ease:'power2.inOut'},cue('mentira',B));
tl.to('#editorial,#bridgeNote',{y:-140,opacity:0,duration:.4,ease:'power2.in'},Q-.3);
enter('#example',Q,{y:10});enter('#paperWorld',Q,{y:180,rotation:5,scale:.85},.75);
tl.to('#paperWorld',{scale:1.08,y:0,duration:.7,ease:'power2.inOut'},Q+1);tl.set('#under',{opacity:0},0);enter('#ask',Q,{y:30},.35);enter('#answer',cue('sim',Q),{y:35,scale:.92},.4);enter('#approve',cue('aprova',Q)-.3,{y:20},.3);
enter('#cursor',cue('aprova',Q)-.6,{y:100},.3);tl.to('#cursor',{x:-180,y:-200,duration:.5,ease:'power2.inOut'},cue('aprova',Q)-.3);tl.to('#approve',{scale:.96,duration:.09,yoyo:true,repeat:1},cue('aprova',Q));enter('#stamp',cue('aprova',Q)+.15,{scale:1.45},.18);hide('#cursor',cue('aprova',Q)+.4);
const C=cue('custo',Q);tl.set('#under',{opacity:1},C-.2);tl.to('#receipt',{rotation:-9,y:-1160,opacity:0,duration:.8,ease:'power3.inOut'},C-.3);tl.to('#paperWorld',{scale:1.04,y:-20,duration:.8,ease:'power2.inOut'},C-.3);
enter('#cost',C,{x:80},.45);enter('#freight',cue('frete',Q),{x:80},.45);enter('#profit',cue('conta',Q),{y:25},.4);enter('#sale',cue('venda',Q),{y:25},.3);tl.to('#profitBar',{scaleX:0,backgroundColor:'#b56246',duration:1.1,ease:'power2.in'},cue('venda',Q));enter('#profitEnd',cue('lucro',Q),{y:25},.4);
tl.to('#paperWorld',{scale:.75,rotation:5,x:-1050,opacity:0,duration:.7,ease:'power3.inOut'},P-.2);hide('#example',P);enter('#process',P,{y:65},.5);
enter('#n1',cue('dados',P),{x:-170,rotation:-5},.65);enter('#n2',cue('conta',P),{x:170,rotation:5},.65);enter('#n3',cue('alguém',P),{y:100},.65);tl.set('#l1,#l2',{scaleY:0},0);tl.to('#l1',{scaleY:1,duration:.45},cue('conta',P)-.3);tl.to('#l2',{scaleY:1,duration:.45},cue('alguém',P)-.3);tl.set('#beam',{opacity:0,top:400},0);tl.set('#beam',{opacity:1},cue('conta',P));tl.to('#beam',{y:400,duration:cue('aprovar',P)-cue('conta',P),ease:'none'},cue('conta',P));hide('#beam',cue('aprovar',P));
['#n1 .tick','#n2 .tick','#n3 .tick'].forEach((id,i)=>enter(id,[cue('conferidos',P),cue('cálculo',P),cue('aprovar',P)][i],{scale:2},.3));
tl.to('#process',{scale:.78,y:-120,opacity:0,duration:.65,ease:'power3.inOut'},F+1.5);enter('#final',F+2,{y:100},.65);enter('#finalcard',cue('diagnóstico',F),{y:65,rotation:-3},.65);
let groups=[],g=[];W.forEach(w=>{if(g.length&&(g.length>=7||w.s-g.at(-1).e>.65||w.who!==g[0].who)){groups.push(g);g=[];}g.push(w);if(/[.?!]$/.test(w.w)){groups.push(g);g=[];}});if(g.length)groups.push(g);
groups.forEach((a,i)=>{const d=document.createElement('div');d.className='caption';d.id='cap'+i;d.textContent=a.map(w=>w.w).join(' ');if(a[0].who==='moises')d.style.top='1540px';document.getElementById('captions').appendChild(d);tl.set(d,{opacity:1},a[0].s);tl.set(d,{opacity:0},Math.min(groups[i+1]?.[0].s??T,a.at(-1).e+.25));});
tl.set('#root',{opacity:1},T);
'''
html=f'<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script><style>{css}</style></head><body><div id="root" data-composition-id="main" data-start="0" data-duration="{T}" data-width="1080" data-height="1920">{body}</div><script>const D={json.dumps(t,ensure_ascii=False)};{js}</script></body></html>'
(p/'index.html').write_text(html)
print('motion pronto',T)
